package com.campus.student.infrastructure.persistence;
import java.util.*; import com.campus.student.application.StudentManagementService.ConcurrentStudentModificationException; import com.campus.student.domain.*; import com.campus.student.infrastructure.persistence.entity.StudentEntity; import org.springframework.stereotype.Repository; import org.springframework.transaction.annotation.Transactional;
@Repository class StudentPersistenceAdapter implements StudentRepository { private final StudentJpaRepository repo; StudentPersistenceAdapter(StudentJpaRepository repo){this.repo=repo;} @Transactional public Student save(Student s){return managed(repo.findById(s.id()).orElseGet(()->new StudentEntity(s.id())),s);} @Transactional public Student saveMutation(Student s,long version){StudentEntity e=repo.findByIdForUpdate(s.id()).orElseThrow(); if(e.getRowVersion()!=version)throw new ConcurrentStudentModificationException(); return managed(e,s);} private Student managed(StudentEntity e,Student s){e.update(s.studentNumber(),s.fullName(),s.email(),s.organizationUnitId(),s.status()); return map(repo.saveAndFlush(e));} @Transactional(readOnly=true) public Optional<Student> findById(UUID id){return repo.findById(id).map(this::map);} @Transactional(readOnly=true) public boolean existsByStudentNumber(String n){return repo.existsByStudentNumber(n);} @Transactional(readOnly=true) public List<Student> findAll(){return repo.findAll(org.springframework.data.domain.Sort.by("studentNumber")).stream().map(this::map).toList();} private Student map(StudentEntity e){return new Student(e.getId(),e.getStudentNumber(),e.getFullName(),e.getEmail(),e.getOrganizationUnitId(),e.getStatus(),e.getRowVersion(),e.getCreatedAt(),e.getUpdatedAt());} }
